from __future__ import annotations

from uuid import UUID

from pydantic import Field
from typing_extensions import NotRequired, TypedDict

from ..core import UNSET, Optional, SdkBaseModel
from .enums.report_type import ReportTypeOrStr
from .enums.request_status import RequestStatusOrStr
from .payload12 import Payload12, Payload12Dict


class RequestStatusResponse(SdkBaseModel):
    request_id: Optional[UUID] = Field(default=UNSET, alias="requestId")
    """Automated ID generated by system that uniquely identifies the report request."""

    request_status: Optional[RequestStatusOrStr] = Field(default=UNSET, alias="requestStatus")
    """Status of report request. Possible values are RECEIVED, INPROGRESS, READY, ERROR."""

    request_submission_date: Optional[str] = Field(default=UNSET, alias="requestSubmissionDate")
    """Date and time on which the report request is submitted."""

    report_type: Optional[ReportTypeOrStr] = Field(default=UNSET, alias="reportType")
    """Type of report for which the request is created. Example, ITEM for Item Report."""

    report_version: Optional[str] = Field(default=UNSET, alias="reportVersion")
    """Version of report for which the request is created. Example, v1."""

    payload: Optional[Payload12] = UNSET
    """Request Payload"""

    report_generation_date: Optional[str] = Field(default=UNSET, alias="reportGenerationDate")
    """Date and time on which the report is generated. Attribute is available only if report is generated."""


class RequestStatusResponseDict(TypedDict):
    request_id: NotRequired[UUID]
    request_status: NotRequired[RequestStatusOrStr]
    request_submission_date: NotRequired[str]
    report_type: NotRequired[ReportTypeOrStr]
    report_version: NotRequired[str]
    payload: NotRequired[Payload12Dict]
    report_generation_date: NotRequired[str]
